  String toString() => 'Point($x, $y)';


  int get hashCode => Object.hash(x.hashCode, y.hashCode);


  bool operator ==(Object other) {
    if (other is! Point) return false;
    return x == other.x && y == other.y;
  }


  static Point fromString(String s) {
    final parts = s.trim().split(',').map((p) => p.trim()).toList();
    if (parts.length != 2) {
      throw FormatException('Invalid format. Expected "x,y"');
    }
    try {
      final x = double.parse(parts[0]);
      final y = double.parse(parts[1]);
      return Point(x, y);
    } catch (_) {
      throw FormatException('Cannot parse coordinates in "$s"');
    }
  }


  Point translate(double dx, double dy) => Point(x + dx, y + dy);


  double distanceTo(Point other) => ((this.x - other.x).pow(2) + 
                                     (this.y - other.y).pow(2)).sqrt();
}

