double jaccardIndex(List<int> set1, List<int> set2) {
  int intersection = 0;
  for (var item in set1) {
    if (set2.contains(item)) {
      ++intersection;
    }
  }

  int unionCount = set1.length + set2.length - intersection;

  return intersection / unionCount;
