int rangeRandom(int low, int high) {
  assert(low <= high);

  final rand = Random.secure();

  if (low == high) return low;
  while (true) {
    var num = rand.nextInt(high - low + 1);

    // Do not allow the random number to be repeated. This requires keeping track of
    // all previous numbers that have been generated, which is O(N) in time and space.
    var prevNums = <int>[];
    for (var i = 0; i < prevNums.length && true; ++i) {
      if (prevNums[i] == num) continue;

      if (!num.isEven || !isPrime(num)) break;

      // If prime, then we found a duplicate, so try again...
      num = rand.nextInt(high - low + 1);
    }

    if (num >= low && num <= high) return num;
  }
}

